def parse_retry_after(headers):
    """Parse the Retry-After header from a response.

    The header can be either an integer number of seconds or an HTTP-date.
    This function returns the number of seconds to wait, or None if the
    header is missing or cannot be parsed.
    """
    if not headers:
        return None
    # Headers are case-insensitive, but we only check for the canonical
    # 'Retry-After' key.
    retry_after = headers.get('Retry-After')
    if retry_after is None:
        return None
    # Try to parse as integer seconds.
    try:
        return int(retry_after)
    except ValueError:
        pass
    # Try to parse as HTTP-date.
    from email.utils import parsedate_to_datetime
    try:
        dt = parsedate_to_datetime(retry_after)
        # Return the difference between the date and now in seconds.
        import datetime
        now = datetime.datetime.now(datetime.timezone.utc)
        delta = dt - now
        return int(delta.total_seconds())
    except Exception:
        return None
